// generated by gemini-3.5-flash-lite for PR #5792 (round 0): flatten_ordered_json_order
// intent: Verify that ordered_json preserves the iteration and entry order after flattening.
#include <nlohmann/json.hpp>
#include <iostream>

int main() {
    try {
        nlohmann::ordered_json j = {{"z", 1}, {"a", 2}, {"m", {{"y", 3}, {"b", 4}}}};
        auto flat = j.flatten();
        for (auto it = flat.begin(); it != flat.end(); ++it) {
            std::cout << it.key() << ": " << it.value() << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
}
